H, W, K = map(int, input().split())
S = [list(input()) for _ in range(H)]

min_operations = float('inf')

# Check rows
for s in S:
    for start in range(W - K + 1):
        count = 0
        for i in range(start, start + K):
            if s[i] == '.':
                count += 1
        min_operations = min(min_operations, count)

# Transpose the grid to check columns
S_t = [list(x) for x in zip(*S)]

# Check columns
for s in S_t:
    for start in range(H - K + 1):
        count = 0
        for i in range(start, start + K):
            if s[i] == '.':
                count += 1
        min_operations = min(min_operations, count)

print(min_operations if min_operations != float('inf') else -1)
